import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3, mix, float, mul, add, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    MeshBasicMaterial,
    LineBasicMaterial,
    EdgesGeometry,
    LineSegments,
    DirectionalLight,
    PointLight,
    Color
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();
  root.name = config.id ?? 'features-stat-tile';

  const resources = [];
  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.086, 0.086, 0.114),
      backdropUv.y
    ),
    backdropUv.y
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6, 1, 1),
    backdropMaterial
  );
  backdrop.name = 'designed-stage-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowMaterial = new MeshBasicMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    new CircleGeometry(1.8, 48),
    shadowMaterial
  );
  contactShadow.name = 'machined-card-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.25, 0.42, 1);
  contactShadow.position.set(0, -1.03, -0.12);
  root.add(contactShadow);

  const cardGeometry = new PlaneGeometry(3.15, 1.72, 64, 64);
  const cardMaterial = new MeshStandardNodeMaterial();
  cardMaterial.color.set(colors.surface);
  cardMaterial.roughness = 0.62;
  cardMaterial.metalness = 0.48;
  cardMaterial.colorNode = vec3(0.043, 0.043, 0.063);

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'features-stat-machined-surface';
  card.position.y = -0.4;
  card.position.z = 0.08;
  card.castShadow = true;
  card.receiveShadow = true;
  root.add(card);

  const edgeGeometry = new EdgesGeometry(new PlaneGeometry(3.15, 1.72, 1, 1));
  const edgeMaterial = new LineBasicMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.92
  });
  const accentEdge = new LineSegments(edgeGeometry, edgeMaterial);
  accentEdge.name = 'focus-accent-edge';
  accentEdge.position.copy(card.position);
  accentEdge.position.z += 0.012;
  accentEdge.visible = false;
  root.add(accentEdge);

  const keyLight = new DirectionalLight(new Color(colors.paper), 1.05);
  keyLight.position.set(3.2, 4.2, 4.5);
  root.add(keyLight);

  const rimLight = new PointLight(new Color(colors.accent), 0.62, 7, 2);
  rimLight.position.set(-2.4, 1.7, 2.2);
  root.add(rimLight);

  const fillLight = new PointLight(new Color(colors.paper), 0.28, 6, 2);
  fillLight.position.set(1.8, -1.4, 2.5);
  root.add(fillLight);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl)
      .then((imageTexture) => {
        if (disposed) {
          imageTexture.dispose?.();
          return;
        }

        resources.push(imageTexture);
        if ('colorSpace' in imageTexture && THREE.SRGBColorSpace) {
          imageTexture.colorSpace = THREE.SRGBColorSpace;
        }

        cardMaterial.colorNode = texture(imageTexture, uv());
        cardMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl)
      .then((depthTexture) => {
        if (disposed) {
          depthTexture.dispose?.();
          return;
        }

        resources.push(depthTexture);

        const depth = texture(depthTexture, uv()).r;
        cardMaterial.positionNode = add(
          positionLocal,
          mul(normalLocal, mul(depth, float(0.14)))
        );
        cardMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.position,
    { y: -0.4, z: 0.08 },
    {
      y: 0,
      z: 0.08,
      duration: 0.7,
      ease: 'power3.out'
    }
  );
  entrance.fromTo(
    card.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    },
    '<'
  );
  timelines.push(entrance);

  const primitiveResults = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const run = ctx.primitives[primitive.name](root, primitive.params);
    if (run) {
      primitiveResults.push(run);
      if (typeof run.cleanup === 'function') {
        primitiveCleanups.push(run.cleanup);
      }
      if (run.timeline) {
        timelines.push(run.timeline);
      }
    }
  }

  let hoverTween;
  let pressTimeline;

  const handlers = {
    hover(active) {
      if (disposed) return;

      hoverTween?.kill();
      hoverTween = gsap.to(card.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out'
      });

      if (active) {
        edgeMaterial.color.set(colors.accent);
        accentEdge.visible = true;
      } else {
        accentEdge.visible = false;
        edgeMaterial.color.set(colors.ink);
      }
    },

    click() {
      if (disposed) return;

      pressTimeline?.kill();
      pressTimeline = gsap.timeline();
      pressTimeline
        .to(card.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.out'
        })
        .to(card.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.36,
          ease: 'back.out(2)'
        });

      ctx.emit('hub-features.select', {
        nodeId: config.id ?? 'features-stat-tile'
      });
    },

    focus(active) {
      if (disposed) return;
      accentEdge.visible = Boolean(active);
      edgeMaterial.color.set(active ? colors.accent : colors.ink);
    }
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    hoverTween?.kill();
    pressTimeline?.kill();

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) material.dispose?.();
      }
    });

    for (const resource of resources) {
      resource.dispose?.();
    }

    root.clear();
  };

  return root;
}
